import { randomUUID } from 'node:crypto';
import path from 'node:path';
import process from 'node:process';

import { FAILURE_CODES, codedError } from './contracts.mjs';
import { captureIcacls, runIcacls } from './commands.mjs';
import { PROBE_PREFIX } from './input-inventory.mjs';
import { openOwnedRoot } from './owned-fs.mjs';

export const DENIAL_OPERATIONS = [
  'overwrite',
  'append',
  'create',
  'delete',
  'rename',
];

const DENIAL_ERROR_CODES = new Set(['EACCES', 'EPERM', 'EROFS']);

// Probe files are disposable artifacts generated by this run; refusing any
// other name keeps probe writes/deletes from touching unrelated files.
export const assertProbePath = (probePath) => {
  if (!path.basename(probePath).startsWith(PROBE_PREFIX)) {
    throw new Error(`not a registered denial probe path: ${probePath}`);
  }
};

export const createProbeRecords = (target) =>
  DENIAL_OPERATIONS.map((operation) => ({
    operation,
    probePath: path.join(target, `${PROBE_PREFIX}${operation}-${randomUUID()}`),
  }));

// Probe I/O is confined to the protected root (`target`) the probe belongs to,
// and to names this run generated.
export const writeProbeFile = async (target, probePath) => {
  assertProbePath(probePath);
  const owned = await openOwnedRoot(target);
  await owned.writeFile(probePath, 'probe');
};

export const removeProbeFile = async (target, probePath) => {
  assertProbePath(probePath);
  const owned = await openOwnedRoot(target);
  await owned.rm(probePath, { force: true });
};

export const currentIdentity = () => {
  const username = process.env.USERNAME;
  if (!username) throw new Error('Windows username is required for ACL freeze');
  return process.env.USERDOMAIN
    ? `${process.env.USERDOMAIN}\\${username}`
    : username;
};

// Evidence for an unenforced deny: the ACL as Windows reports it after the
// probe ran. Best-effort - a failure here must not mask the probe result.
export const describeAcl = async (probePath) => {
  try {
    const { stdout } = await captureIcacls(probePath, []);
    return stdout.trim();
  } catch (error_) {
    return `icacls failed: ${error_?.message ?? error_}`;
  }
};

export const assertFreezeIdentityNotDenied = async (target, identity) => {
  const { stdout, stderr } = await captureIcacls(target, ['/t', '/c']);
  const output = `${stdout}\n${stderr}`;
  if (
    output
      .split(/\r?\n/u)
      .some((line) => line.includes(identity) && line.includes('(DENY)'))
  ) {
    throw codedError(
      FAILURE_CODES.EXECUTION_INCOMPLETE,
      `ACL freeze deny entry remains for ${identity}`,
    );
  }
};

const performProbeOperation = async (operation, target, probePath) => {
  assertProbePath(probePath);
  const owned = await openOwnedRoot(target);
  switch (operation) {
    case 'overwrite':
      await owned.writeFile(probePath, 'overwrite');
      break;
    case 'append':
      await owned.appendFile(probePath, 'append');
      break;
    case 'create':
      await owned.writeFile(`${probePath}-new`, 'create');
      break;
    case 'delete':
      await owned.unlink(probePath);
      break;
    case 'rename':
      // Both operands are proven to be inside the protected root.
      await owned.rename(probePath, `${probePath}-renamed`);
      break;
    default:
      break;
  }
};

export const runDenialProbe = async (operation, target, probePath) => {
  try {
    await performProbeOperation(operation, target, probePath);
    return { operation, denied: false, target };
  } catch (error_) {
    const errorCode = error_?.code;
    return {
      operation,
      denied: DENIAL_ERROR_CODES.has(errorCode),
      target,
      ...(errorCode ? { errorCode } : {}),
    };
  } finally {
    await removeProbeFile(target, `${probePath}-new`).catch(() => undefined);
    await removeProbeFile(target, `${probePath}-renamed`).catch(
      () => undefined,
    );
  }
};

export const releaseSingleFrozenTarget = async (
  frozenTarget,
  ownerIdentity,
) => {
  let targetError;
  try {
    await runIcacls(frozenTarget.target, [
      '/remove:d',
      ownerIdentity,
      '/t',
      '/c',
    ]);
    await runIcacls(frozenTarget.target, [
      '/restore',
      frozenTarget.backupPath,
      '/c',
    ]);
  } catch (error_) {
    targetError = error_;
  }
  for (const probePath of frozenTarget.probePaths) {
    try {
      await removeProbeFile(frozenTarget.target, probePath);
    } catch (error_) {
      targetError ??= error_;
    }
  }
  return targetError;
};
